TEST_SECONDS = 60


def run_test(root, test_id):
    try:
        p = subprocess.run([sys.executable, '-B', '-m', 'unittest', test_id], cwd=os.path.join(root, 'tests'), capture_output=True, text=True, timeout=TEST_SECONDS)
    except subprocess.TimeoutExpired:
        return False, 'timed out'          # a guard whose removal makes the code block (a FIFO opened by SQLite) is a failing test
    return p.returncode == 0, p.stderr.strip().splitlines()[-1] if p.stderr.strip() else ''


